// Generated by AI (UnitTest MCP)
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { afterEach, describe, expect, it } from "vitest";

import { readFragments } from "../../../scripts/gaps.mjs";

const directories = [];

const sandbox = (files) => {
  const root = mkdtempSync(join(tmpdir(), "gaps-"));
  directories.push(root);
  mkdirSync(join(root, "gaps.d"));
  for (const [name, body] of Object.entries(files)) {
    writeFileSync(join(root, "gaps.d", name), body, "utf8");
  }
  return join(root, "gaps.d");
};

afterEach(() => {
  for (const directory of directories.splice(0)) {
    rmSync(directory, { recursive: true, force: true });
  }
});

describe("Known Gap lifecycle", () => {
  it("rejects a terminal status with no explicit open residual", () => {
    const directory = sandbox({
      "closed.md": "- **The defect is gone — FIXED.** Historical detail.\n",
    });

    const { gaps, problems } = readFragments(directory);

    expect(gaps).toEqual([]);
    expect(problems[0]).toMatch(/terminal status.*delete the fragment/i);
  });

  it("accepts partial fixes and prose when the status remains open", () => {
    const directory = sandbox({
      "partial.md": "- **The first half is FIXED; cross-crate resolution remains OPEN.** Detail.\n",
      "prose.md": "- **Bindings are fixed to the tree as it was — MEASURED, OPEN.** Detail.\n",
    });

    const { gaps, problems } = readFragments(directory);

    expect(problems).toEqual([]);
    expect(gaps.map((gap) => gap.name)).toEqual(["partial.md", "prose.md"]);
  });
});
